#endif
    public func uniffiClonePointer() -> UnsafeMutableRawPointer {
        return try! rustCall { uniffi_featherkey_core_fn_clone_sensitivefield(self.pointer, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        guard let pointer = pointer else {
            return
        }

        try! rustCall { uniffi_featherkey_core_fn_free_sensitivefield(pointer, $0) }
    }

    

    
open func isSensitive() -> Bool {
    return try!  FfiConverterBool.lift(try! rustCall() {
    uniffi_featherkey_core_fn_method_sensitivefield_is_sensitive(self.uniffiClonePointer(),$0
    )
})
}
    

}
// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
private let IDX_CALLBACK_FREE: Int32 = 0
// Callback return codes
private let UNIFFI_CALLBACK_SUCCESS: Int32 = 0
private let UNIFFI_CALLBACK_ERROR: Int32 = 1
private let UNIFFI_CALLBACK_UNEXPECTED_ERROR: Int32 = 2

// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceSensitiveField {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    static var vtable: UniffiVTableCallbackInterfaceSensitiveField = UniffiVTableCallbackInterfaceSensitiveField(
        isSensitive: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutablePointer<Int8>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> Bool in
                guard let uniffiObj = try? FfiConverterTypeSensitiveField.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.isSensitive(
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterBool.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterTypeSensitiveField.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface SensitiveField: handle missing in uniffiFree")
            }
        }
    )
}

private func uniffiCallbackInitSensitiveField() {
    uniffi_featherkey_core_fn_init_callback_vtable_sensitivefield(&UniffiCallbackInterfaceSensitiveField.vtable)
}

