/**
 * A decoded key candidate for the shell to render.
 */
public struct FfiCandidate {
    public var key: String
    public var confidence: Float

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(key: String, confidence: Float) {
        self.key = key
        self.confidence = confidence
    }
}



extension FfiCandidate: Equatable, Hashable {
    public static func ==(lhs: FfiCandidate, rhs: FfiCandidate) -> Bool {
        if lhs.key != rhs.key {
            return false
        }
        if lhs.confidence != rhs.confidence {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(key)
        hasher.combine(confidence)
    }
}


