/**
 * An autocorrect decision.
 */
public struct FfiCorrection {
    public var primary: String
    public var alternatives: [String]
    public var applied: Bool
    /**
     * When the neural gate withheld an otherwise-available correction
     * (`applied == false` but a winner existed), the winner it declined to
     * apply — mirrors [`featherkey_contracts::Correction::withheld`]. `None`
     * when nothing was withheld (a correction applied, or there was no
     * candidate to gate). The shell surfaces this as the counterfactual
     * "reached" signal for `observe_autocorrect_outcome`.
     */
    public var withheld: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(primary: String, alternatives: [String], applied: Bool, 
        /**
         * When the neural gate withheld an otherwise-available correction
         * (`applied == false` but a winner existed), the winner it declined to
         * apply — mirrors [`featherkey_contracts::Correction::withheld`]. `None`
         * when nothing was withheld (a correction applied, or there was no
         * candidate to gate). The shell surfaces this as the counterfactual
         * "reached" signal for `observe_autocorrect_outcome`.
         */withheld: String?) {
        self.primary = primary
        self.alternatives = alternatives
        self.applied = applied
        self.withheld = withheld
    }
}



extension FfiCorrection: Equatable, Hashable {
    public static func ==(lhs: FfiCorrection, rhs: FfiCorrection) -> Bool {
        if lhs.primary != rhs.primary {
            return false
        }
        if lhs.alternatives != rhs.alternatives {
            return false
        }
        if lhs.applied != rhs.applied {
            return false
        }
        if lhs.withheld != rhs.withheld {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(primary)
        hasher.combine(alternatives)
        hasher.combine(applied)
        hasher.combine(withheld)
    }
}


