// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * The real-world outcome of the last gated correction (Task 9's training
 * signal), marshalled across the FFI. Mirrors [`AutocorrectOutcome`] 1:1.
 */

public enum FfiAutocorrectOutcome {
    
    /**
     * The user reverted/undid it: push the gate toward "withhold".
     */
    case reverted
    /**
     * The user kept it, with no strong signal either way.
     */
    case kept
    /**
     * The user typed on past it cleanly: a confirming signal.
     */
    case reached
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiAutocorrectOutcome: FfiConverterRustBuffer {
    typealias SwiftType = FfiAutocorrectOutcome

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiAutocorrectOutcome {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .reverted
        
        case 2: return .kept
        
        case 3: return .reached
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiAutocorrectOutcome, into buf: inout [UInt8]) {
        switch value {
        
        
        case .reverted:
            writeInt(&buf, Int32(1))
        
        
        case .kept:
            writeInt(&buf, Int32(2))
        
        
        case .reached:
            writeInt(&buf, Int32(3))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiAutocorrectOutcome_lift(_ buf: RustBuffer) throws -> FfiAutocorrectOutcome {
    return try FfiConverterTypeFfiAutocorrectOutcome.lift(buf)
}

