@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiAutocorrectOutcome_lower(_ value: FfiAutocorrectOutcome) -> RustBuffer {
    return FfiConverterTypeFfiAutocorrectOutcome.lower(value)
}



