/**
 * The single flat error the whole surface returns. Mirrors [`FeatherKeyError`]
 * plus the two FFI-only failures (bad key length, store-open failure).
 */
public enum FfiError {

    
    
    case NoLanguages
    case Lexicon
    case Locale
    case EmptyLayout
    case TouchModel
    case Store
    case BadKeyLength
    case StoreOpen
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NoLanguages
        case 2: return .Lexicon
        case 3: return .Locale
        case 4: return .EmptyLayout
        case 5: return .TouchModel
        case 6: return .Store
        case 7: return .BadKeyLength
        case 8: return .StoreOpen

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NoLanguages:
            writeInt(&buf, Int32(1))
        
        
        case .Lexicon:
            writeInt(&buf, Int32(2))
        
        
        case .Locale:
            writeInt(&buf, Int32(3))
        
        
        case .EmptyLayout:
            writeInt(&buf, Int32(4))
        
        
        case .TouchModel:
            writeInt(&buf, Int32(5))
        
        
        case .Store:
            writeInt(&buf, Int32(6))
        
        
        case .BadKeyLength:
            writeInt(&buf, Int32(7))
        
        
        case .StoreOpen:
            writeInt(&buf, Int32(8))
        
        }
    }
}


