/**
 * The Latin arrangement a user picked, or `Auto` (per-language default).
 * Mirrors [`crate::LatinLayout`] plus an `Auto` variant for "no override".
 */

public enum FfiLatinLayout {
    
    case auto
    case qwerty
    case qwertz
    case azerty
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiLatinLayout: FfiConverterRustBuffer {
    typealias SwiftType = FfiLatinLayout

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiLatinLayout {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .auto
        
        case 2: return .qwerty
        
        case 3: return .qwertz
        
        case 4: return .azerty
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiLatinLayout, into buf: inout [UInt8]) {
        switch value {
        
        
        case .auto:
            writeInt(&buf, Int32(1))
        
        
        case .qwerty:
            writeInt(&buf, Int32(2))
        
        
        case .qwertz:
            writeInt(&buf, Int32(3))
        
        
        case .azerty:
            writeInt(&buf, Int32(4))
        
        }
    }
}


